head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//팩스첨부문서
scwin.vScrenID = "ULDINS91100.xml";
scwin.sKEY = "";
scwin.sGubun = "";
scwin.onpageload = function() {

};
scwin.onpageunload = function() {
}; // 1 : 발행기관신청,  팩스-발행기관신청  2:표준코드신청, 팩스-표준코드신청   3:팩스-다운로드IP  로 넣어주세요~~~

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 발행기관 신청 상세정보
 ***********************************************/
scwin.ins_search = function() {
    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_FileList);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.common.select.listAttachFileInquiry" + "&outputMessageId=ULDINS91100_LIST_OUT" + "&param01=" + scwin.sKEY + "&param02=" + scwin.sGubun;
    //alert( url);
    dts_FileList.DataID = encodeURI(url);
    dts_FileList.Reset();
};


/**
 * 파일다운로드
 */
scwin.fn_DownloadFile = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_08);
    var nRow = dts_FileList.getRowPosition();
    var sKEY1 = dts_FileList.getCellData(nRow, "KEY1");
    var sKEY2 = dts_FileList.getCellData(nRow, "KEY2");
    var sGubun = dts_FileList.getCellData(nRow, "FILE_DN_FG");

    // GUBUN
    // 1 : 발행기관신청 첨부파일
    // 2 : 표준코드신청 첨부파일
    // 3 : FAX 첨부파일
    location.href = "/filedownload.do?KEY1=" + sKEY1 + "&KEY2=" + sKEY2 + "&GUBUN=" + scwin.sGubun;
};
scwin.gform_onload = async function() {
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar != undefined) {
        fn_GetPar(arrPar);
        scwin.sKEY = arrPar[0];
        scwin.sGubun = arrPar[1];
        if (scwin.sKEY == "") {
            $c.win.alert("조회 키(접수번호 등)가 없습니다.");
            await $c.frame.CloseFrame();
            return;
        }
        if (scwin.sGubun == "") {
            var sMsg = "구분값이 없습니다. \n\n" + "1 : 발행기관신청, 팩스-발행기관신청 \n" + "2 : 표준코드신청, 팩스-표준코드신청 \n" + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n";
            $c.win.alert(sMsg);
            await $c.frame.CloseFrame();
            return;
        }
        scwin.ins_search();
    }
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.grd_FileList_OnDblClick = function(row, colid) {
    if (row == 0) return;
    // 파일 다운로드
    scwin.fn_DownloadFile();
};
scwin.dts_FileList_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_FileList);
    $c.stf.alert_error(dts_FileList);
};
scwin.dts_FileList_OnLoadCompleted = function(rowcount) {
    if (dts_FileList.errorMsg) {
        $c.win.alert(dts_FileList.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_FileList);
};
